// Valida el payload recibido de Odoo (contrato tickets.created) y arma
// los campos listos para la plantilla de WhatsApp (parametros posicionales).
// Ver README (docs/n8n_workflows/raffle_whatsapp_README.md) para el contrato completo.

const body = ($input.first().json.body) || $input.first().json;

const partner = body.partner || {};
const campaign = body.campaign || {};
const tickets = body.tickets || {};
const portalUrl = body.portal_url || '';

// res.partner.phone en Odoo 19 (ya no existe 'mobile' separado). Se espera
// formato E.164 (+52...); si Odoo lo manda con espacios/guiones los quitamos,
// pero si no empieza con '+' lo tratamos como invalido (mejor omitir que
// enviar a un numero mal formado).
const rawPhone = String(partner.phone || '').replace(/[\s-]/g, '');
const hasValidPhone = /^\+[1-9]\d{7,14}$/.test(rawPhone);

const folios = Array.isArray(tickets.folios) ? tickets.folios : [];
const foliosPreview = folios.length
  ? folios.slice(0, 5).join(', ') + (folios.length > 5 ? ` y ${folios.length - 5} mas` : '')
  : 'N/A';

return [{
  json: {
    to: rawPhone,
    has_valid_phone: hasValidPhone,
    partner_id: partner.id || null,
    partner_name: partner.name || '',
    campaign_id: campaign.id || null,
    campaign_name: campaign.name || '',
    campaign_code: campaign.code || '',
    ticket_count: tickets.count || folios.length || 0,
    folios_preview: foliosPreview,
    portal_url: portalUrl,
    raw_event: body,
  },
}];
